#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// 2D fields: i x j, with j the inner (contiguous) dimension
	//   Layout proto: scalar ^ (j_vec ^ i_vec) ^ set_space
	//   => outer dimension 'i', inner (contiguous) dimension 'j'
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec);
	// 1D fictitious array over time
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);
} tuning;

// Array initialization
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Initialize fict[t] = t
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = (num_t)t;
	});

	// Dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Initialize ex, ey, hz
	traverser(ex, ey, hz).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		ex[state] = ((num_t)i * (j + 1)) / (num_t)nx;
		ey[state] = ((num_t)i * (j + 2)) / (num_t)ny;
		hz[state] = ((num_t)i * (j + 3)) / (num_t)nx;
	});
}

/*
 * Optimized FDTD-2D kernel
 *
 * Semantics (per time step t):
 *   1) Boundary: ey[0, j]        = fict[t]                    for j in [0, ny)
 *   2) ey update: ey[i, j]      -= 0.5 * (hz[i, j] - hz[i-1, j])
 *      for i in [1, nx), j in [0, ny)
 *   3) ex update: ex[i, j]      -= 0.5 * (hz[i, j] - hz[i, j-1])
 *      for i in [0, nx), j in [1, ny)
 *   4) hz update: hz[i, j]      -= 0.7 * ((ex[i, j+1] - ex[i, j]) +
 *                                          (ey[i+1, j] - ey[i, j]))
 *      for i in [0, nx-1), j in [0, ny-1)
 *
 * Transformations:
 *   - Time loop kept sequential (for_dims<'t'>).
 *   - Spatial tiling in both i and j using into_blocks_dynamic:
 *       i -> (I, i) with guard dim 'si'
 *       j -> (J, j) with guard dim 'sj'
 *     The guard dimensions ensure correctness when nx, ny are not
 *     multiples of tile sizes; invalid (i, j) combinations are simply
 *     not visited.
 *   - For ex/ey interior (i >= 1, j >= 1), we fuse the two updates so
 *     that hz[i, j] is loaded only once and reused, improving bandwidth.
 *   - we keep j as the innermost spatial dimension to preserve
 *     unit-stride access in the row-major layout (i outer, j inner).
 */
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Tunable spatial tile sizes (chosen to fit well into L1/L2).
	// 32x32 tiles => at most ~3 * 32 * 32 * sizeof(num_t) bytes for
	// ex/ey/hz working set per tile, which fits comfortably into cache
	// for both float and double.
	constexpr std::size_t tile_i = 32;
	constexpr std::size_t tile_j = 32;

	// Precompute constants once
	const num_t c_ex_ey = SCALAR_VAL(0.5);
	const num_t c_hz    = SCALAR_VAL(0.7);

#pragma scop
	// Time stepping: inherently sequential
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// Current time state; contains only 't'
		auto t_state = trav_t.state();
		// Load fict[t] once per time step and reuse
		const num_t fict_t = fict[t_state];

		// -----------------------------------------------------------------
		// 1) Boundary condition: ey[0, j] = fict[t] for all j
		//    We tile along j for better cache behavior when NY is large.
		// -----------------------------------------------------------------
		trav_t
			.order(
				noarr::fix<'i'>(0) ^
				noarr::into_blocks_dynamic<'j', 'J', 'j', 'sj'>(tile_j)
			)
			.template for_dims<'J'>([=](auto trav_J) {
				// trav_J: 'J' fixed, 'j' within the tile, guard 'sj'
				trav_J.for_each([=](auto state) {
					// state has: t, i=0, j, sj (guard)
					// The guard 'sj' ensures we skip invalid j in the last tile.
					ey[state] = fict_t;
				});
			});

		// -----------------------------------------------------------------
		// 2) ey update for j = 0 (first column), i in [1, nx)
		//    ey[i, 0] -= 0.5 * (hz[i, 0] - hz[i-1, 0])
		// -----------------------------------------------------------------
		trav_t
			.order(
				noarr::slice<'i'>(1, nx - 1) ^    // i in [1, nx-1]
				noarr::fix<'j'>(0) ^              // j = 0
				noarr::into_blocks_dynamic<'i', 'I', 'i', 'si'>(tile_i)
			)
			.template for_dims<'I'>([=](auto trav_I) {
				// trav_I: 'I' fixed, 'i' inside tile, guard 'si'
				trav_I.template for_dims<'i'>([=](auto trav_i) {
					// trav_i: 'i' fixed, guard 'si' still present
					trav_i.for_each([=](auto state) {
						// Domain: i in [1, nx-1], j = 0
						auto state_im1j = state - noarr::idx<'i'>(1);

						ey[state] = ey[state]
						           - c_ex_ey * (hz[state] - hz[state_im1j]);
					});
				});
			});

		// -----------------------------------------------------------------
		// 3) Fused interior updates for ey and ex on i >= 1, j >= 1:
		//
		//    ey[i, j] -= 0.5 * (hz[i, j] - hz[i-1, j])
		//    ex[i, j] -= 0.5 * (hz[i, j] - hz[i, j-1])
		//
		// Both depend only on hz at the current time level and write to
		// disjoint arrays, so they can be safely fused.
		// We tile in both i and j to improve data locality.
		// -----------------------------------------------------------------
		trav_t
			.order(
				noarr::slice<'i'>(1, nx - 1) ^    // i in [1, nx-1]
				noarr::slice<'j'>(1, ny - 1) ^    // j in [1, ny-1]
				noarr::into_blocks_dynamic<'i', 'I', 'i', 'si'>(tile_i) ^
				noarr::into_blocks_dynamic<'j', 'J', 'j', 'sj'>(tile_j)
			)
			.template for_dims<'I', 'J'>([=](auto trav_tile) {
				// Fix tile indices I, J; now iterate within tile in i, then j.
				trav_tile.template for_dims<'i', 'j'>([=](auto trav_ij) {
					// trav_ij still has guard dims 'si', 'sj'; for_each will
					// iterate them (0 or 1) to discard invalid cells in the
					// last incomplete tiles.
					trav_ij.for_each([=](auto state) {
						// Domain: i in [1, nx-1], j in [1, ny-1]
						const num_t hz_ij   = hz[state];
						const auto  im1j    = state - noarr::idx<'i'>(1);
						const auto  ijm1    = state - noarr::idx<'j'>(1);
						const num_t hz_im1j = hz[im1j];
						const num_t hz_ijm1 = hz[ijm1];

						// ey update (vertical derivative, i-direction)
						ey[state] = ey[state] - c_ex_ey * (hz_ij - hz_im1j);

						// ex update (horizontal derivative, j-direction)
						ex[state] = ex[state] - c_ex_ey * (hz_ij - hz_ijm1);
					});
				});
			});

		// -----------------------------------------------------------------
		// 4) Remaining ex updates along i = 0, j >= 1:
		//    ex[0, j] -= 0.5 * (hz[0, j] - hz[0, j-1])
		// -----------------------------------------------------------------
		trav_t
			.order(
				noarr::fix<'i'>(0) ^               // i = 0
				noarr::slice<'j'>(1, ny - 1) ^     // j in [1, ny-1]
				noarr::into_blocks_dynamic<'j', 'J', 'j', 'sj'>(tile_j)
			)
			.template for_dims<'J'>([=](auto trav_J) {
				trav_J.for_each([=](auto state) {
					// Domain: i = 0, j in [1, ny-1]
					auto ijm1 = state - noarr::idx<'j'>(1);

					ex[state] = ex[state] - c_ex_ey * (hz[state] - hz[ijm1]);
				});
			});

		// -----------------------------------------------------------------
		// 5) hz update using *updated* ex and ey:
		//
		//    hz[i, j] -= 0.7 * ( (ex[i, j+1] - ex[i, j]) +
		//                        (ey[i+1, j] - ey[i, j]) )
		//    for i in [0, nx-1), j in [0, ny-1)
		//
		// Again, we tile in both i and j and keep j as the innermost
		// spatial loop for unit-stride accesses.
		// -----------------------------------------------------------------
		trav_t
			.order(
				noarr::slice<'i'>(0, nx - 1) ^     // i in [0, nx-2]
				noarr::slice<'j'>(0, ny - 1) ^     // j in [0, ny-2]
				noarr::into_blocks_dynamic<'i', 'I', 'i', 'si'>(tile_i) ^
				noarr::into_blocks_dynamic<'j', 'J', 'j', 'sj'>(tile_j)
			)
			.template for_dims<'I', 'J'>([=](auto trav_tile) {
				trav_tile.template for_dims<'i', 'j'>([=](auto trav_ij) {
					trav_ij.for_each([=](auto state) {
						// Domain: i in [0, nx-2], j in [0, ny-2]
						auto i_jp1 = state + noarr::idx<'j'>(1);
						auto ip1_j = state + noarr::idx<'i'>(1);

						const num_t hz_ij = hz[state];
						const num_t dx    = ex[i_jp1] - ex[state];
						const num_t dy    = ey[ip1_j] - ey[state];

						hz[state] = hz_ij - c_hz * (dx + dy);
					});
				});
			});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t tmax = TMAX;
	std::size_t nx = NX;
	std::size_t ny = NY;

	// Set lengths for spatial and temporal dimensions
	auto set_space = noarr::set_length<'i'>(nx) ^ noarr::set_length<'j'>(ny);
	auto set_time  = noarr::set_length<'t'>(tmax);

	// Allocate bags
	auto ex = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto ey = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto hz = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto fict = noarr::bag(noarr::scalar<num_t>() ^ tuning.fict_layout ^ set_time);

	// Initialize arrays
	init_array(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_fdtd_2d(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print results (if requested, mimicking PolyBench's conditional printing)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);

		// Hoist 'i' so each row is contiguous in the serialized output
		noarr::serialize_data(std::cerr, ex.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, ey.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, hz.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print elapsed time (seconds)
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
