// Main computational kernel
//
// Semantics (per time step t):
//   1) ey[0, j] = fict[t]
//   2) ey[i, j] -= 0.5 * (hz[i, j] - hz[i-1, j])      for i ∈ [1, NX), j ∈ [0, NY)
//   3) ex[i, j] -= 0.5 * (hz[i, j] - hz[i, j-1])      for i ∈ [0, NX), j ∈ [1, NY)
//   4) hz[i, j] -= 0.7 * ((ex[i, j+1] - ex[i, j]) +
//                         (ey[i+1, j] - ey[i, j]))    for i ∈ [0, NX-1), j ∈ [0, NY-1)
//
// Optimizations:
//   - Keep memory layout: j is contiguous, i is outer.
//   - Fuse interior ex/ey updates for i>=1, j>=1 so hz[i,j] is loaded once.
//   - Apply 2D tiling in (i, j) via into_blocks_dynamic + hoist to improve cache locality.
//   - Keep all data loops expressed via Noarr traversers; do not introduce raw for-loops.
//
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Problem sizes (can be static or dynamic values; both are fine here)
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// ---------------------------------------------------------------------
	// Tiling configuration
	// ---------------------------------------------------------------------
	// Choose tile sizes that keep 3 * TI * TJ * sizeof(num_t) reasonably
	// small (for ex, ey, hz together). 32 x 64 is a good default for
	// floats and doubles on typical x64 cores.
	constexpr std::size_t tile_i = 32;
	constexpr std::size_t tile_j = 64;

	// 1D tiling in j, used for row-wise operations (boundary and i=0 row)
	//
	//   into_blocks_dynamic<'j','J','j','s'>(tile_j):
	//     - splits j into:
	//         J ... tile index
	//         j ... index inside tile
	//         s ... presence flag for partial tiles
	//   hoist<'J'>():
	//     - moves J towards the outermost loop so we iterate tile-by-tile.
	auto tile_j_proto =
		into_blocks_dynamic<'j', 'J', 'j', 's'>(lit<tile_j>) ^
		hoist<'J'>();

	// 1D tiling in i, used for column-wise operations (j=0 column)
	auto tile_i_proto =
		into_blocks_dynamic<'i', 'I', 'i', 'r'>(lit<tile_i>) ^
		hoist<'I'>();

	// 2D tiling in (i, j) used in the main interior loops.
	// We first tile j (inner / contiguous), then i, hoisting J then I.
	// The final effective iteration order becomes:
	//   I (outer tiles in i), J (tiles in j), i, j (points), which
	// still keeps j as the innermost unit-stride dimension.
	auto tile_ij_proto = tile_j_proto ^ tile_i_proto;

#pragma scop
	// Sequential time-stepping loop driven by fict[t].
	traverser(fict).for_each([=](auto t_state) {
		// Load boundary value once per time step (hoisted out of inner loops)
		num_t ft = fict[t_state];

		// =================================================================
		// 1) Boundary condition: ey[0, j] = fict[t] for all j
		// =================================================================
		//
		// We fix i=0 and iterate j with 1D tiling. Traverser states contain
		// both i and j, but the structure ignores any extra dimensions.
		traverser(ey)
			.order(
				fix<'i'>(0) ^   // restrict to row i = 0
				tile_j_proto    // tile j for cache/SIMD friendliness
			)
			.for_each([=](auto state) {
				// state: i = 0, j in [0, ny)
				ey[state] = ft;
			});

		// =================================================================
		// 2) ey update on column j = 0, i in [1, nx)
		//    ey[i, 0] -= 0.5 * (hz[i, 0] - hz[i-1, 0])
		// =================================================================
		//
		// This is the "left edge" of the domain (j=0). It cannot be fused
		// with the ex-update (which starts at j=1), so we keep it separate.
		traverser(ey, hz)
			.order(
				slice<'i'>(1, nx - 1) ^  // i ∈ [1, nx)
				fix<'j'>(0) ^            // j = 0
				tile_i_proto             // tile along i (column-wise)
			)
			.for_each([=](auto state) {
				// state: i in [1, nx), j = 0
				auto state_im1j = state - idx<'i'>(1);

				ey[state] = ey[state]
				            - SCALAR_VAL(0.5) * (hz[state] - hz[state_im1j]);
			});

		// =================================================================
		// 3) Fused interior ey/ex updates for i >= 1, j >= 1
		//
		//    ey[i, j] -= 0.5 * (hz[i, j] - hz[i-1, j])
		//    ex[i, j] -= 0.5 * (hz[i, j] - hz[i, j-1])
		//
		// Original code had two separate loops.  Here we fuse them because:
		//   - both read only hz[*] at time t,
		//   - they write disjoint fields (ey and ex),
		//   - the relative order of the two updates per (i, j) does not
		//     matter for correctness.
		//
		// This allows us to load hz[i, j] only once and reuse it for both
		// ey and ex updates, improving memory locality and vectorization.
		// =================================================================
		traverser(ex, ey, hz)
			.order(
				// Restrict to interior domain i ∈ [1, nx), j ∈ [1, ny)
				slice<'i'>(1, nx - 1) ^
				slice<'j'>(1, ny - 1) ^
				// 2D tiling; tile_ij_proto only affects traversal order,
				// states still carry the original (i, j) indices.
				tile_ij_proto
			)
			.for_each([=](auto state) {
				// state: i ∈ [1, nx), j ∈ [1, ny)
				auto state_im1j = state - idx<'i'>(1);
				auto state_ijm1 = state - idx<'j'>(1);

				// ey interior update (vertical derivative)
				ey[state] = ey[state]
				            - SCALAR_VAL(0.5) * (hz[state] - hz[state_im1j]);

				// ex interior update (horizontal derivative)
				ex[state] = ex[state]
				            - SCALAR_VAL(0.5) * (hz[state] - hz[state_ijm1]);
			});

		// =================================================================
		// 4) Remaining ex updates along i = 0, j in [1, ny)
		//
		//    ex[0, j] -= 0.5 * (hz[0, j] - hz[0, j-1])
		//
		// These points were not covered by the fused interior loop above
		// (which starts at i = 1), so we handle the boundary row i = 0
		// separately, tiling in j only.
		// =================================================================
		traverser(ex, hz)
			.order(
				fix<'i'>(0) ^             // i = 0
				slice<'j'>(1, ny - 1) ^   // j ∈ [1, ny)
				tile_j_proto
			)
			.for_each([=](auto state) {
				// state: i = 0, j ∈ [1, ny)
				auto state_ijm1 = state - idx<'j'>(1);

				ex[state] = ex[state]
				            - SCALAR_VAL(0.5) * (hz[state] - hz[state_ijm1]);
			});

		// =================================================================
		// 5) hz update on interior:
		//
		//    hz[i, j] -= 0.7 * ( (ex[i, j+1] - ex[i, j])
		//                        + (ey[i+1, j] - ey[i, j]) )
		//    for i ∈ [0, nx-1), j ∈ [0, ny-1)
		//
		// Uses the newly updated ex and ey from steps 2–4.  We tile (i, j)
		// in the same way as in step 3 to improve cache locality.
		// =================================================================
		traverser(ex, ey, hz)
			.order(
				slice<'i'>(0, nx - 1) ^   // i ∈ [0, nx-1)
				slice<'j'>(0, ny - 1) ^   // j ∈ [0, ny-1)
				tile_ij_proto
			)
			.for_each([=](auto state) {
				// state: i ∈ [0, nx-1), j ∈ [0, ny-1)
				auto state_i_jp1 = state + idx<'j'>(1);
				auto state_ip1_j = state + idx<'i'>(1);

				hz[state] = hz[state]
				            - SCALAR_VAL(0.7) * (
					            (ex[state_i_jp1] - ex[state]) +
					            (ey[state_ip1_j] - ey[state])
				            );
			});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t tmax = TMAX;
	std::size_t nx = NX;
	std::size_t ny = NY;

	// Set lengths for spatial and temporal dimensions
	auto set_space = noarr::set_length<'i'>(nx) ^ noarr::set_length<'j'>(ny);
	auto set_time  = noarr::set_length<'t'>(tmax);

	// Allocate bags
	auto ex = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto ey = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto hz = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto fict = noarr::bag(noarr::scalar<num_t>() ^ tuning.fict_layout ^ set_time);

