		// 1) Boundary condition on ey at i = 0:
		//    ey[0][j] = fict[t]  for all j in [0, ny)
		// ------------------------------------------------------------------
		trav_t
			.order(noarr::fix<'i'>(0))
			.for_each([=](auto state) {
				// state has i = 0, all j; t is encoded in t_state
				ey[state] = ft;
			});

