		//   - load hz[i,j] once per cell, and
		//   - update both ey and ex in the same traversal.
		// ------------------------------------------------------------------
		trav_t.for_each([=](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);

			// Reuse central hz[i, j] across both updates
			num_t hz_ij = hz[state];

			// ey[i, j] update (only for i >= 1)
			if (i > 0) {
