		// We keep the same spatial domain as the original kernel using
		// noarr::slice on 'i' and 'j', but introduce temporaries to avoid
		// re-loading ex/ey values.
		// ------------------------------------------------------------------
		trav_t
			.order(noarr::slice<'i'>(0, nx - 1) ^ noarr::slice<'j'>(0, ny - 1))
			.for_each([=](auto state) {
				// state: i in [0, nx-2], j in [0, ny-2]
				auto state_i_jp1 = state + noarr::idx<'j'>(1);
				auto state_ip1_j = state + noarr::idx<'i'>(1);

				// Load neighboring ex/ey values once per iteration
