				noarr::fix<'j'>(0) ^
				noarr::slice<'i'>(1, nx - 1) ^ // restrict to i in [1, nx)
				noarr::into_blocks_dynamic<'i', 'I', 'i', 'ib'>(noarr::lit<tile_i>)
			);

