				noarr::slice<'j'>(1, ny - 1) ^    // j in [1, ny)
				noarr::into_blocks_dynamic<'i', 'I', 'i', 'ib'>(noarr::lit<tile_i>) ^
				noarr::into_blocks_dynamic<'j', 'J', 'j', 'jb'>(noarr::lit<tile_j>)
